result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "caves.py", "content": """"Cellular-automata cave generator.

Pipeline:
  1. Seed a 60x40 grid with 45% wall noise (deterministic per seed).
  2. Run 5 smoothing iterations of the 4-5 rule:
     a cell becomes wall if >= 5 of its 8 neighbors are walls,
     treating out-of-bounds cells as walls.
  3. Flood fill to find connected open regions; keep only the largest
     and fill every other open cell with wall.
"""

from __future__ import annotations

import random
from collections import deque

WIDTH = 60
HEIGHT = 40
WALL_RATIO = 0.45
SMOOTHING_ITERATIONS = 5
RULE_THRESHOLD = 5  # 4-5 rule: wall if >= 5 of 8 neighbors (incl. self? no: neighbors only)

WALL = "#"
OPEN = " "


def _neighbors8(x: int, y: int) -> list[tuple[int, int]]:
    for dy in (-1, 0, 1):
        for dx in (-1, 0, 1):
            if dx == 0 and dy == 0:
                continue
            yield x + dx, y + dy


def _seed_noise(seed: int, width: int, height: int) -> list[list[bool]]:
    """grid[y][x] is True for wall."""
    rng = random.Random(seed)
    return [[rng.random() < WALL_RATIO for _ in range(width)] for _ in range(height)]


def _smooth(grid: list[list[bool]]) -> list[list[bool]]:
    height, width = len(grid), len(grid[0])
    new_grid = [[False] * width for _ in range(height)]
    for y in range(height):
        for x in range(width):
            walls = 0
            for nx, ny in _neighbors8(x, y):
                if nx < 0 or ny < 0 or nx >= width or ny >= height or grid[ny][nx]:
                    walls += 1
            # 4-5 rule: becomes (or stays) wall if 5+ of its 8 neighbors are walls.
            new_grid[y][x] = walls >= RULE_THRESHOLD
    return new_grid


def _open_regions(grid: list[list[bool]]) -> list[list[tuple[int, int]]]:
    """Return all connected open regions (4-connectivity)."""
    height, width = len(grid), len(grid[0])
    seen = [[False] * width for _ in range(height)]
    regions = []
    for y in range(height):
        for x in range(width):
            if grid[y][x] or seen[y][x]:
                continue
            region = []
            queue = deque([(x, y)])
            seen[y][x] = True
            while queue:
                cx, cy = queue.popleft()
                region.append((cx, cy))
                for cx2, cy2 in ((cx + 1, cy), (cx - 1, cy), (cx, cy + 1), (cx, cy - 1)):
                    if (
                        0 <= cx2 < width
                        and 0 <= cy2 < height
                        and not grid[cy2][cx2]
                        and not seen[cy2][cx2]
                    ):
                        seen[cy2][cx2] = True
                        queue.append((cx2, cy2))
            regions.append(region)
    return regions


def generate_cave(
    seed: int,
    width: int = WIDTH,
    height: int = HEIGHT,
    iterations: int = SMOOTHING_ITERATIONS,
) -> list[list[bool]]:
    """Generate a cave grid. grid[y][x] is True for wall, False for open floor."""
    grid = _seed_noise(seed, width, height)
    for _ in range(iterations):
        grid = _smooth(grid)

    regions = _open_regions(grid)
    if regions:
        largest = max(regions, key=len)
        keep = set(largest)
        for y in range(height):
            for x in range(width):
                if not grid[y][x] and (x, y) not in keep:
                    grid[y][x] = True
    return grid


def render(grid: list[list[bool]]) -> str:
    """Render the cave as ASCII art."""
    return "\n".join("".join(WALL if c else OPEN for c in row) for row in grid)


if __name__ == "__main__":
    print(render(generate_cave(1)))
"})
