from caves import HEIGHT, WIDTH, generate_cave


def is_wall(grid, x, y):
    return grid[y][x]


@pytest.mark.parametrize("seed", range(1, 16))
def test_border_all_walls(seed):
    grid = generate_cave(seed)
    assert len(grid) == HEIGHT
    assert all(len(row) == WIDTH for row in grid)
    for x in range(WIDTH):
        assert is_wall(grid, x, 0), f"top border open at ({x}, 0)"
        assert is_wall(grid, x, HEIGHT - 1), f"bottom border open at ({x}, {HEIGHT - 1})"
    for y in range(HEIGHT):
        assert is_wall(grid, 0, y), f"left border open at (0, {y})"
        assert is_wall(grid, WIDTH - 1, y), f"right border open at ({WIDTH - 1}, {y})"


def count_regions(grid):
    seen = set()
    regions = 0
    start = next(
        (x, y) for y in range(HEIGHT) for x in range(WIDTH) if not grid[y][x]
    )
    stack = [start]
    while stack:
        pos = stack.pop()
        if pos in seen:
            continue
        seen.add(pos)
        x, y = pos
        for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
            if 0 <= nx < WIDTH and 0 <= ny < HEIGHT and not grid[ny][nx]:
                stack.append((nx, ny))
    return regions


@pytest.mark.parametrize("seed", range(1, 16))
def test_exactly_one_open_region(seed):
    grid = generate_cave(seed)
    open_cells = {(x, y) for y in range(HEIGHT) for x in range(WIDTH) if not grid[y][x]}
    if not open_cells:
        pytest.fail("no open cells at all")
    # BFS from one open cell must reach every other open cell.
    start = next(iter(open_cells))
    stack = [start]
    seen = set()
    while stack:
        pos = stack.pop()
        if pos in seen:
            continue
        seen.add(pos)
        x, y = pos
        for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
            if (nx, ny) in open_cells:
                stack.append((nx, ny))
    assert seen == open_cells


@pytest.mark.parametrize("seed", range(1, 16))
def test_open_area_fraction(seed):
    grid = generate_cave(seed)
    open_count = sum(not c for row in grid for c in row)
    fraction = open_count / (WIDTH * HEIGHT)
    assert 0.25 <= fraction <= 0.60, f"open fraction {fraction:.3f} out of bounds"


@pytest.mark.parametrize("seed", range(1, 16))
def test_deterministic_per_seed(seed):
    g1 = generate_cave(seed)
    g2 = generate_cave(seed)
    assert g1 == g2


@pytest.mark.parametrize("s1,s2", [(a, a + 1) for a in range(1, 15)])
def test_different_seeds_differ(s1, s2):
    g1 = generate_cave(s1)
    g2 = generate_cave(s2)
    assert g1 != g2
